-- Fixed IDs and offset timestamps make the seed reproducible across environments.
-- Switching the demo profile off keeps any data already in the database.
INSERT INTO tournaments (id, name)
SELECT id::uuid, name FROM (VALUES
    ('10000000-0000-4000-8000-000000000001', 'Riverside Cup 2026'),
    ('10000000-0000-4000-8000-000000000002', 'Westbrook Friendly')
) AS demo(id, name)
WHERE ${demo_enabled}
ON CONFLICT (id) DO NOTHING;

INSERT INTO teams (id, tournament_id, name)
SELECT id::uuid, '10000000-0000-4000-8000-000000000001', name FROM (VALUES
    ('20000000-0000-4000-8000-000000000001', 'Riverside Rovers'),
    ('20000000-0000-4000-8000-000000000002', 'Northgate United'),
    ('20000000-0000-4000-8000-000000000003', 'Oakfield Athletic'),
    ('20000000-0000-4000-8000-000000000004', 'Westbrook FC'),
    ('20000000-0000-4000-8000-000000000005', 'Eastvale Town'),
    ('20000000-0000-4000-8000-000000000006', 'Hillcrest City'),
    ('20000000-0000-4000-8000-000000000007', 'Lakeside Wanderers'),
    ('20000000-0000-4000-8000-000000000008', 'Meadow Park FC')
) AS demo(id, name)
WHERE ${demo_enabled}
ON CONFLICT (id) DO NOTHING;

INSERT INTO fields (id, tournament_id, name)
SELECT id::uuid, '10000000-0000-4000-8000-000000000001', name FROM (VALUES
    ('30000000-0000-4000-8000-000000000001', 'Main Pitch'),
    ('30000000-0000-4000-8000-000000000002', 'North Pitch'),
    ('30000000-0000-4000-8000-000000000003', 'South Pitch')
) AS demo(id, name)
WHERE ${demo_enabled}
ON CONFLICT (id) DO NOTHING;

INSERT INTO matches (id, tournament_id, home_team_id, away_team_id, field_id, starts_at, ends_at)
SELECT id::uuid, '10000000-0000-4000-8000-000000000001', home_id::uuid, away_id::uuid,
       field_id::uuid, starts_at::timestamptz, ends_at::timestamptz
FROM (VALUES
    ('40000000-0000-4000-8000-000000000001', '20000000-0000-4000-8000-000000000001', '20000000-0000-4000-8000-000000000002', '30000000-0000-4000-8000-000000000001', '2026-11-28T09:00:00Z', '2026-11-28T10:00:00Z'),
    ('40000000-0000-4000-8000-000000000002', '20000000-0000-4000-8000-000000000003', '20000000-0000-4000-8000-000000000004', '30000000-0000-4000-8000-000000000002', '2026-11-28T09:30:00Z', '2026-11-28T10:30:00Z'),
    ('40000000-0000-4000-8000-000000000003', '20000000-0000-4000-8000-000000000005', '20000000-0000-4000-8000-000000000006', '30000000-0000-4000-8000-000000000003', '2026-11-28T10:30:00Z', '2026-11-28T11:30:00Z'),
    ('40000000-0000-4000-8000-000000000004', '20000000-0000-4000-8000-000000000007', '20000000-0000-4000-8000-000000000008', '30000000-0000-4000-8000-000000000001', '2026-11-28T11:00:00Z', '2026-11-28T12:00:00Z'),
    ('40000000-0000-4000-8000-000000000005', '20000000-0000-4000-8000-000000000002', '20000000-0000-4000-8000-000000000003', '30000000-0000-4000-8000-000000000001', '2026-11-29T09:00:00Z', '2026-11-29T10:00:00Z'),
    ('40000000-0000-4000-8000-000000000006', '20000000-0000-4000-8000-000000000004', '20000000-0000-4000-8000-000000000005', '30000000-0000-4000-8000-000000000002', '2026-11-29T09:30:00Z', '2026-11-29T10:30:00Z'),
    ('40000000-0000-4000-8000-000000000007', '20000000-0000-4000-8000-000000000006', '20000000-0000-4000-8000-000000000007', '30000000-0000-4000-8000-000000000003', '2026-11-29T10:30:00Z', '2026-11-29T11:30:00Z'),
    ('40000000-0000-4000-8000-000000000008', '20000000-0000-4000-8000-000000000008', '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000001', '2026-11-29T11:00:00Z', '2026-11-29T12:00:00Z')
) AS demo(id, home_id, away_id, field_id, starts_at, ends_at)
WHERE ${demo_enabled}
ON CONFLICT (id) DO NOTHING;
